l_int32 generate_html_image_viewer(const char* dirin, const char* dirout, const char* rootname, l_int32 thumbwidth, l_int32 viewwidth) {
    // Check for valid input parameters
    if (!dirin || !dirout || !rootname || thumbwidth <= 0 || viewwidth <= 0) {
        return 1; // Error: Invalid parameters
    }

    // Create the output directory if it doesn't exist
    if (makeDir(dirout)) {
        return 2; // Error: Failed to create output directory
    }

    // Retrieve filenames from the input directory
    FILELIST* filelist = getFilenamesInDirectory(dirin, NULL, 0);
    if (!filelist) {
        return 3; // Error: Failed to retrieve files from input directory
    }

    // Process each image file to generate thumbnails and view images
    for (l_int32 i = 0; i < filelist->box.n; ++i) {
        char* filename = getBoxedString(filelist, i);
        char* fullpath = genPathname(dirin, filename);
        PIX* pix = pixRead(fullpath);
        if (!pix) {
            FREE(fullpath);
            continue; // Skip invalid or unreadable files
        }

        // Generate thumbnail and view image
        PIX* thumb = pixScaleToWidth(pix, thumbwidth);
        PIX* view = pixScaleToWidth(pix, viewwidth);

        // Save generated images to the output directory
        char thumbpath[256];
        char viewpath[256];
        snprintf(thumbpath, sizeof(thumbpath), "%s/%s_thumb.jpg", dirout, filename);
        snprintf(viewpath, sizeof(viewpath), "%s/%s_view.jpg", dirout, filename);

        pixWrite(thumbpath, thumb, IFF_JPEG);
        pixWrite(viewpath, view, IFF_JPEG);

        // Clean up
        pixDestroy(&thumb);
        pixDestroy(&view);
        pixDestroy(&pix);
        FREE(fullpath);
    }

    // Create HTML files
    char indexpath[256];
    char fullviewpath[256];
    snprintf(indexpath, sizeof(indexpath), "%s/%s_index.html", dirout, rootname);
    snprintf(fullviewpath, sizeof(fullviewpath), "%s/%s_fullview.html", dirout, rootname);

    FILE* indexfile = fopen(indexpath, "w");
    FILE* fullviewfile = fopen(fullviewpath, "w");

    if (!indexfile || !fullviewfile) {
        return 4; // Error: Failed to create HTML files
    }

    // Write HTML content
    for (l_int32 i = 0; i < filelist->box.n; ++i) {
        char* filename = getBoxedString(filelist, i);
        char thumbpath[256];
        char viewpath[256];
        snprintf(thumbpath, sizeof(thumbpath), "%s_thumb.jpg", filename);
        snprintf(viewpath, sizeof(viewpath), "%s_view.jpg", filename);

        fprintf(indexfile, "<a href=\"%s\"><img src=\"%s\" alt=\"Thumbnail\"></a>\n", viewpath, thumbpath);
        fprintf(fullviewfile, "<img src=\"%s\" alt=\"View Image\">\n", viewpath);
    }

    // Clean up
    fclose(indexfile);
    fclose(fullviewfile);
    filelistDestroy(&filelist);

    return 0; // Success
}

l_int32 generate_html_viewer(const char* dirin, const char* dirout, const char* rootname, l_int32 thumbwidth, l_int32 viewwidth) {
    l_int32 result = 0;
    char* outdir = NULL;
    char* html1 = NULL;
    char* html2 = NULL;
    char* outpath = NULL;

    if (!dirin || !dirout || !rootname) {
        return 1; // Error: invalid input parameters
    }

    // Create the output directory if it doesn't exist
    if ((result = makePath(dirout, &outdir)) != 0) {
        return result;
    }

    // Get filenames from the input directory
    SARRAY* filenames = getFilenames(dirin);
    if (!filenames) {
        return 2; // Error: no files found or couldn't read directory
    }

    l_int32 count = sarrayGetCount(filenames);
    for (l_int32 i = 0; i < count; ++i) {
        const char* filename = sarrayGetString(filenames, i, L_NOCOPY);

        // Generate paths for original image, thumbnail, and view image
        char* origpath = makePath(dirin, filename);
        char* thumbpath = makePath(dirout, filename);
        char* viewpath = makePath(dirout, filename);

        // Generate thumbnail and view image
        Pix* pix = pixRead(origpath);
        if (!pix) {
            result = 3; // Error: failed to read image
            FREE(origpath);
            FREE(thumbpath);
            FREE(viewpath);
            continue;
        }

        Pix* pixThumb = pixScaleToWidth(pix, thumbwidth);
        Pix* pixView = pixScaleToWidth(pix, viewwidth);

        // Save thumbnail and view image
        pixWrite(thumbpath, pixThumb, IFF_JPEG);
        pixWrite(viewpath, pixView, IFF_JPEG);

        // Clean up
        pixDestroy(&pix);
        pixDestroy(&pixThumb);
        pixDestroy(&pixView);

        FREE(origpath);
        FREE(thumbpath);
        FREE(viewpath);
    }

    // Generate HTML files
    html1 = genHtmlIndex(dirout, rootname, filenames, thumbwidth);
    html2 = genHtmlView(dirout, rootname, filenames, viewwidth);

    if (!html1 || !html2) {
        result = 4; // Error: failed to generate HTML
    }

    // Save HTML files
    outpath = makePath(dirout, html1);
    fpIO* fp = fopenWrite(outpath);
    if (!fp) {
        result = 5; // Error: failed to open file for writing
    } else {
        fwrite(html1, sizeof(char), strlen(html1), fp);
        fclose(fp);
    }
    FREE(outpath);
    FREE(html1);

    outpath = makePath(dirout, html2);
    fp = fopenWrite(outpath);
    if (!fp) {
        result = 5; // Error: failed to open file for writing
    } else {
        fwrite(html2, sizeof(char), strlen(html2), fp);
        fclose(fp);
    }
    FREE(outpath);
    FREE(html2);

    sarrayDestroy(&filenames);
    FREE(outdir);

    return result;
}

