l_int32 generate_html_image_viewer(const char* dirin, const char* dirout, const char* rootname, l_int32 thumbwidth, l_int32 viewwidth) {
    l_int32 result = 0;
    l_int32 count = 0;
    char* htmlfn = NULL;
    char* fulloutdir = NULL;
    char* thumbdir = NULL;
    char* viewdir = NULL;
    char* linkdir = NULL;
    char* htmlfn1 = NULL;
    char* htmlfn2 = NULL;
    PIX* pixs = NULL;
    BOX* box = NULL;
    PTA* ptas = NULL;
    L_FILELIST* fl = NULL;
    L_FILE* fp = NULL;

    if (!dirin || !dirout || !rootname) {
        return ERROR_PTR("generate_html_image_viewer: invalid input", "generate_html_image_viewer", &result);
    }

    if ((fulloutdir = stringJoin(dirout, "/")) == NULL)
        return ERROR_PTR("generate_html_image_viewer: fulloutdir", "generate_html_image_viewer", &result);

    if (makeDirectory(fulloutdir, 0777, 0))
        return ERROR_PTR("generate_html_image_viewer: makeDirectory", "generate_html_image_viewer", &result);

    if ((fl = fileListCreate(dirin, NULL, 1)) == NULL)
        return ERROR_PTR("generate_html_image_viewer: fileListCreate", "generate_html_image_viewer", &result);

    count = fl->n;
    if (count == 0) {
        L_ERROR("generate_html_image_viewer: no files in directory\n", "generate_html_image_viewer");
        result = 1;
        goto cleanup;
    }

    if ((htmlfn1 = stringJoin(rootname, "_index.html")) == NULL)
        return ERROR_PTR("generate_html_image_viewer: htmlfn1", "generate_html_image_viewer", &result);
    if ((htmlfn2 = stringJoin(rootname, "_index_links.html")) == NULL)
        return ERROR_PTR("generate_html_image_viewer: htmlfn2", "generate_html_image_viewer", &result);

    if ((fp = fopenWriteStream(htmlfn1, "w")) == NULL)
        return ERROR_PTR("generate_html_image_viewer: htmlfn1 stream", "generate_html_image_viewer", &result);

    fprintf(fp, "<html>\n<head>\n<title>Images</title>\n</head>\n<body>\n<h1>Images</h1>\n");

    for (l_int32 i = 0; i < count; i++) {
        char* fn = fl->files[i];
        char* fullin = stringJoin(dirin, "/");
        char* fullinfn = stringJoin(fullin, fn);
        char* thumbfn = stringJoin(rootname, "_thumb/");
        char* viewfn = stringJoin(rootname, "_view/");
        char* thumbout = stringJoin(fulloutdir, "/");
        char* thumboutfn = stringJoin(thumbout, thumbfn);
        char* viewout = stringJoin(fulloutdir, "/");
        char* viewoutfn = stringJoin(viewout, viewfn);

        if ((pixs = pixRead(fullinfn)) == NULL)
            continue;

        if ((box = boxCreate(0, 0, pixGetWidth(pixs), pixGetHeight(pixs))) == NULL)
            continue;

        if ((ptas = ptaCreate(0)) == NULL)
            continue;

        if ((pixs = pixScaleToWidth(pixs, thumbwidth)) == NULL)
            continue;
        if (pixWrite(thumboutfn, pixs, IFF_JPEG) != 0)
            continue;

        if ((pixs = pixRead(fullinfn)) == NULL)
            continue;
        if ((pixs = pixScaleToWidth(pixs, viewwidth)) == NULL)
            continue;
        if (pixWrite(viewoutfn, pixs, IFF_JPEG) != 0)
            continue;

        fprintf(fp, "<p><a href=\"%s\"><img src=\"%s\" alt=\"\"></a></p>\n", viewfn, thumbfn);
    }

    fprintf(fp, "</body>\n</html>\n");
    fcloseStream(fp);

    if ((fp = fopenWriteStream(htmlfn2, "w")) == NULL)
        return ERROR_PTR("generate_html_image_viewer: htmlfn2 stream", "generate_html_image_viewer", &result);

    fprintf(fp, "<html>\n<head>\n<title>Image Links</title>\n</head>\n<body>\n<h1>Image Links</h1>\n<ul>\n");

    for (l_int32 i = 0; i < count; i++) {
        char* fn = fl->files[i];
        char* viewfn = stringJoin(rootname, "_view/");
        char* viewoutfn = stringJoin(fulloutdir, "/");
        char* fullviewfn = stringJoin(viewoutfn, viewfn);
        fprintf(fp, "<li><a href=\"%s\">%s</a></li>\n", fullviewfn, fn);
    }

    fprintf(fp, "</ul>\n</body>\n</html>\n");
    fcloseStream(fp);

cleanup:
    LEPT_FREE(htmlfn);
    LEPT_FREE(fulloutdir);
    LEPT_FREE(thumbdir);
    LEPT_FREE(viewdir);
    LEPT_FREE(linkdir);
    LEPT_FREE(htmlfn1);
    LEPT_FREE(htmlfn2);
    LEPT_FREE(fullin);
    LEPT_FREE(fullinfn);
    LEPT_FREE(thumbfn);
    LEPT_FREE(viewfn);
    LEPT_FREE(thumbout);
    LEPT_FREE(thumboutfn);
    LEPT_FREE(viewout);
    LEPT_FREE(viewoutfn);

    if (fl)
        fileListDestroy(&fl);
    if (pixs)
        pixDestroy(&pixs);
    if (box)
        boxDestroy(&box);
    if (ptas)
        ptaDestroy(&ptas);
    if (fp)
        fclose(fp);

    return result;
}

#include <stdio.h>
