l_int32 generate_image_html_viewer(const char* dirin, const char* dirout, const char* rootname, l_int32 thumbwidth, l_int32 viewwidth) {
    if (!dirin || !dirout || !rootname || thumbwidth <= 0 || viewwidth <= 0) {
        return 1;  // Invalid input
    }

    // Create output directory if it doesn't exist
    struct stat st = {0};
    if (stat(dirout, &st) == -1) {
        if (mkdir(dirout, 0777) != 0) {
            return 2;  // Failed to create output directory
        }
    }

    // Open the input directory
    DIR* dir = opendir(dirin);
    if (!dir) {
        return 3;  // Failed to open input directory
    }

    struct dirent* entry;
    l_int32 count = 0;
    char** filenames = NULL;

    // Retrieve filenames from the input directory
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG) {
            char* filename = entry->d_name;

            // Assume we're handling only common image file types
            if (strstr(filename, ".jpg") || strstr(filename, ".jpeg") || strstr(filename, ".png") || strstr(filename, ".gif")) {
                filenames = (char**)realloc(filenames, (count + 1) * sizeof(char*));
                filenames[count] = strdup(filename);
                count++;
            }
        }
    }
    closedir(dir);

    if (count == 0) {
        return 4;  // No image files found
    }

    // Generate thumbnails and view images for each image
    for (l_int32 i = 0; i < count; i++) {
        char input_path[1024];
        char thumb_path[1024];
        char view_path[1024];

        snprintf(input_path, sizeof(input_path), "%s/%s", dirin, filenames[i]);
        snprintf(thumb_path, sizeof(thumb_path), "%s/%s_thumb.jpg", dirout, filenames[i]);
        snprintf(view_path, sizeof(view_path), "%s/%s_view.jpg", dirout, filenames[i]);

        // Assume functions to generate thumbnails and view images are available
        generate_thumbnail(input_path, thumb_path, thumbwidth);
        generate_view_image(input_path, view_path, viewwidth);
    }

    // Generate the HTML file with thumbnails and view links
    char html1_path[1024];
    snprintf(html1_path, sizeof(html1_path), "%s/%s.html", dirout, rootname);

    FILE* html1 = fopen(html1_path, "w");
    if (!html1) {
        return 5;  // Failed to create HTML file
    }

    fprintf(html1, "<html><body>\n");
    for (l_int32 i = 0; i < count; i++) {
        char thumb_img_path[1024];
        char view_img_path[1024];
        char base_filename[1024];

        // Remove the file extension for cleaner HTML display
        strncpy(base_filename, filenames[i], sizeof(base_filename));
        char* dot = strrchr(base_filename, '.');
        if (dot) {
            *dot = '\0';
        }

        snprintf(thumb_img_path, sizeof(thumb_img_path), "%s/%s_thumb.jpg", dirout, filenames[i]);
        snprintf(view_img_path, sizeof(view_img_path), "%s/%s_view.jpg", dirout, filenames[i]);

        fprintf(html1, "<a href=\"%s\"><img src=\"%s\" alt=\"%s\" /></a>\n", view_img_path, thumb_img_path, base_filename);
    }
    fprintf(html1, "</body></html>\n");
    fclose(html1);

    // Generate the HTML file with view image links
    char html2_path[1024];
    snprintf(html2_path, sizeof(html2_path), "%s/%s_links.html", dirout, rootname);

    FILE* html2 = fopen(html2_path, "w");
    if (!html2) {
        return 6;  // Failed to create HTML file
    }

    fprintf(html2, "<html><body>\n");
    for (l_int32 i = 0; i < count; i++) {
        char view_img_path[1024];
        char base_filename[1024];

        strncpy(base_filename, filenames[i], sizeof(base_filename));
        char* dot = strrchr(base_filename, '.');
        if (dot) {
            *dot = '\0';
        }

        snprintf(view_img_path, sizeof(view_img_path), "%s/%s_view.jpg", dirout, filenames[i]);

        fprintf(html2, "<p><a href=\"%s\">%s</a></p>\n", view_img_path, base_filename);
    }
    fprintf(html2, "</body></html>\n");
    fclose(html2);

    // Free allocated memory
    for (l_int32 i = 0; i < count; i++) {
        free(filenames[i]);
    }
    free(filenames);

    return 0;
}
